mapper.select:
SELECT qvr.id, qvr.question_id AS questionId, q.title AS questionTitle, q.difficulty AS questionDifficulty, qvr.view_date AS viewDate, qvr.create_time AS createTime FROM question_view_record qvr INNER JOIN question q ON q.id = qvr.question_id WHERE qvr.user_id = #{userId} AND q.is_delete = 0
AND qvr.id < #{cursor}
ORDER BY qvr.id DESC LIMIT #{limit}
